import Foundation

public struct MemoryLearningEvidence: Codable, Equatable, Sendable { public enum Role: String, Codable, Sendable { case user, assistant, memory }; public let sourceId: String; public let role: Role; public let start: Int; public let end: Int; public let sha256: String }
public struct MemoryLearningPolicy: Codable, Equatable, Sendable {
    public var revision: Int; public var scopeEpoch: Int; public var enabled: Bool; public var maintenanceEnabled: Bool; public var dreamingEnabled: Bool
    public var minIdleMs: Int; public var maxJobsPerDay: Int; public var maxProposalsPerJob: Int; public var timezone: String; public var nightHour: Int?
    public let botRevision: Int; public let profileId: String; public let grantRevision: Int; public let actionId: String?; public let updatedAt: Int64
}
public struct MemoryLearningStatus: Codable, Equatable, Sendable {
    public let botId: String; public let policy: MemoryLearningPolicy; public let effectiveEnabled: Bool; public let mode: String
    public enum Extractor: String, Codable, Sendable { case officialDriver = "official_driver", unconfigured }; public enum Backend: String, Codable, Sendable { case availableUnverified = "available_unverified", unavailable }; public let extractor: Extractor; public let backend: Backend; public let purge: String; public let history: String; public let reason: String?
}
public struct MemoryLearningCandidate: Codable, Equatable, Identifiable, Sendable {
    public enum Kind: String, Codable, Sendable { case preference, fact, procedure, hypothesis, contradiction }; public enum Confidence: String, Codable, Sendable { case explicit, supported, uncertain }; public enum State: String, Codable, Sendable { case pending, accepted, rejected, withdrawn }; public let id: String; public let content: String; public let kind: Kind; public let confidence: Confidence; public let evidence: [MemoryLearningEvidence]
    public let expectedRevision: Int; public let scopeEpoch: Int; public let policyRevision: Int; public let state: State; public let jobId: String; public let createdAt: Int64
    public var target: MemoryLearningCommand.Target { .init(id: id, expectedRevision: expectedRevision, policyRevision: policyRevision, scopeEpoch: scopeEpoch) }
}
public struct MemoryLearningRecord: Codable, Equatable, Identifiable, Sendable {
    public let id: String; public let content: String?; public let kind: String; public let revision: Int; public let sha256: String; public let scopeEpoch: Int
    public enum State: String, Codable, Sendable { case active, archived, expired, forgotten }; public let state: State; public let evidence: [MemoryLearningEvidence]; public let createdAt: Int64
}
public struct MemoryLearningJob: Codable, Equatable, Identifiable, Sendable {
    public enum Kind: String, Codable, Sendable { case capture, dreaming }; public enum State: String, Codable, Sendable { case queued, claimed, dispatched, proposed, empty, unknown, withdrawn, conflict }; public let id: String; public let kind: Kind; public let state: State; public let inputHash: String; public let scopeEpoch: Int; public let policyRevision: Int
    public let fence: Int; public let createdAt: Int64; public let updatedAt: Int64
}
public struct MemoryLearningReceipt: Codable, Equatable, Sendable {
    public let actionId: String; public let botId: String; public let ownerId: String; public let requestHash: String; public let operation: String
    public let inputHash: String; public let result: JSONValue; public let committedAt: Int64
}
public enum MemoryLearningCommand: Equatable, Sendable, Encodable {
    public struct Target: Codable, Equatable, Sendable {
        public let id: String; public let expectedRevision: Int; public let policyRevision: Int; public let scopeEpoch: Int
        public init(id: String, expectedRevision: Int, policyRevision: Int, scopeEpoch: Int) { self.id = id; self.expectedRevision = expectedRevision; self.policyRevision = policyRevision; self.scopeEpoch = scopeEpoch }
    }
    public struct PolicyUpdate: Codable, Equatable, Sendable {
        public static let minimumIdleMs = 120000, maximumJobsPerDay = 8, maximumProposalsPerJob = 4
        public var expectedRevision: Int; public var enabled: Bool; public var maintenanceEnabled: Bool; public var dreamingEnabled: Bool
        public var minIdleMs: Int; public var maxJobsPerDay: Int; public var maxProposalsPerJob: Int; public var timezone: String; public var nightHour: Int?
        public init(expectedRevision: Int, enabled: Bool, maintenanceEnabled: Bool, dreamingEnabled: Bool, minIdleMs: Int = 120000, maxJobsPerDay: Int = 8, maxProposalsPerJob: Int = 4, timezone: String = "America/Sao_Paulo", nightHour: Int? = nil) { self.expectedRevision = expectedRevision; self.enabled = enabled; self.maintenanceEnabled = maintenanceEnabled; self.dreamingEnabled = dreamingEnabled; self.minIdleMs = minIdleMs; self.maxJobsPerDay = maxJobsPerDay; self.maxProposalsPerJob = maxProposalsPerJob; self.timezone = timezone; self.nightHour = nightHour }
        enum CodingKeys: String, CodingKey { case expectedRevision, enabled, maintenanceEnabled, dreamingEnabled, minIdleMs, maxJobsPerDay, maxProposalsPerJob, timezone, nightHour }
        public func encode(to encoder: any Encoder) throws { var c = encoder.container(keyedBy: CodingKeys.self); try c.encode(expectedRevision, forKey: .expectedRevision); try c.encode(enabled, forKey: .enabled); try c.encode(maintenanceEnabled, forKey: .maintenanceEnabled); try c.encode(dreamingEnabled, forKey: .dreamingEnabled); try c.encode(minIdleMs, forKey: .minIdleMs); try c.encode(maxJobsPerDay, forKey: .maxJobsPerDay); try c.encode(maxProposalsPerJob, forKey: .maxProposalsPerJob); try c.encode(timezone, forKey: .timezone); try c.encode(nightHour, forKey: .nightHour) }
    }
    public struct Maintenance: Codable, Equatable, Sendable {
        public let policyRevision: Int; public let scopeEpoch: Int
        public init(policyRevision: Int, scopeEpoch: Int) { self.policyRevision = policyRevision; self.scopeEpoch = scopeEpoch }
    }
    case policyUpdate(PolicyUpdate), candidateAccept(Target), candidateReject(Target), recordArchive(Target), recordForget(Target), recordUndo(Target), maintenanceRun(policyRevision: Int, scopeEpoch: Int)
    public var operation: String { switch self { case .policyUpdate: "policy.update"; case .candidateAccept: "candidate.accept"; case .candidateReject: "candidate.reject"; case .recordArchive: "record.archive"; case .recordForget: "record.forget"; case .recordUndo: "record.undo"; case .maintenanceRun: "maintenance.run" } }
    public var summary: String { switch self { case .policyUpdate: "Alterar aprendizagem de memória"; case .candidateAccept: "Guardar proposta de memória"; case .candidateReject: "Rejeitar proposta de memória"; case .recordArchive: "Arquivar memória"; case .recordForget: "Esquecer memória e bloquear reaprendizagem"; case .recordUndo: "Reativar memória arquivada"; case .maintenanceRun: "Organizar memórias aceitas" } }
    public var details: String { switch self { case .policyUpdate(let p): "Aprendizagem: \(p.enabled ? "ativa" : "desligada"); manutenção: \(p.maintenanceEnabled); revisão \(p.expectedRevision). Máximo de \(p.maxJobsPerDay) jobs por dia e \(p.maxProposalsPerJob) propostas por job. Fuso: \(p.timezone)."; case .candidateAccept(let t), .candidateReject(let t), .recordArchive(let t), .recordForget(let t), .recordUndo(let t): "Registro \(t.id); revisão \(t.expectedRevision), política \(t.policyRevision), escopo \(t.scopeEpoch). Esquecer bloqueia uso e reaprendizagem imediatamente; histórico e backups continuam retidos."; case .maintenanceRun(let revision, let epoch): "Política \(revision), escopo \(epoch). Arquiva duplicatas exatas e expira registros vencidos; propostas semânticas continuam sujeitas a aprovação." } }
    private enum CodingKeys: String, CodingKey { case operation, input }
    public func encode(to encoder: any Encoder) throws { var c = encoder.container(keyedBy: CodingKeys.self); try c.encode(operation, forKey: .operation); switch self { case .policyUpdate(let v): try c.encode(v, forKey: .input); case .candidateAccept(let v), .candidateReject(let v), .recordArchive(let v), .recordForget(let v), .recordUndo(let v): try c.encode(v, forKey: .input); case .maintenanceRun(let revision, let epoch): try c.encode(Maintenance(policyRevision: revision, scopeEpoch: epoch), forKey: .input) } }
}
public struct MemoryLearningRequestObservation: Decodable, Sendable { public let action: Action?; public let command: JSONValue?; public let clientRequestId: String }
public struct MemoryLearningReceiptObservation: Decodable, Sendable { public let action: Action; public let receipt: MemoryLearningReceipt? }
private struct MemoryLearningProposalBody: Encodable { let clientRequestId: String; let command: MemoryLearningCommand }
private struct MemoryLearningPage<Value: Decodable & Sendable>: Decodable, Sendable { let items: [Value] }
private func learningHash(_ value: String) -> Bool { value.count == 64 && value.allSatisfy { "0123456789abcdef".contains($0) } }
private func learningID(_ value: String) throws -> String { guard !value.isEmpty, value.utf8.count <= 128, value.allSatisfy({ $0.isASCII && ($0.isLetter || $0.isNumber || "_.:-".contains($0)) }) else { throw HostClientError.invalidRequest }; return value }
extension HostClient {
    private func learningPath(_ session: OwnerConfigurationSession) throws -> String { guard case .loopbackDevelopment = accessPolicy, UUID(uuidString: session.sessionID) != nil else { throw HostClientError.forbidden }; return "/v1/owner-configuration/sessions/" + session.sessionID + "/memory-learning" }
    public func memoryLearningStatus(_ session: OwnerConfigurationSession) async throws -> MemoryLearningStatus { let v: MemoryLearningStatus = try await request(try learningPath(session) + "/status", timeout: 15); guard v.botId == session.botID, v.mode == "propose", v.history == "retained", v.policy.minIdleMs >= 120000, (1...8).contains(v.policy.maxJobsPerDay), (1...4).contains(v.policy.maxProposalsPerJob) else { throw HostClientError.contractMismatch }; return v }
    public func memoryLearningCandidates(_ session: OwnerConfigurationSession) async throws -> [MemoryLearningCandidate] { let v: MemoryLearningPage<MemoryLearningCandidate> = try await request(try learningPath(session) + "/candidates", timeout: 15); guard v.items.count <= 100, v.items.allSatisfy({ $0.content.utf16.count <= 4096 && $0.evidence.count <= 8 && $0.evidence.allSatisfy({ learningHash($0.sha256) && $0.end > $0.start && $0.start >= 0 && $0.end - $0.start <= 8192 }) }) else { throw HostClientError.contractMismatch }; return v.items }
    public func memoryLearningRecords(_ session: OwnerConfigurationSession) async throws -> [MemoryLearningRecord] { let v: MemoryLearningPage<MemoryLearningRecord> = try await request(try learningPath(session) + "/records", timeout: 15); guard v.items.count <= 100, v.items.allSatisfy({ learningHash($0.sha256) && ($0.state != .forgotten || $0.content == nil) }) else { throw HostClientError.contractMismatch }; return v.items }
    public func memoryLearningJobs(_ session: OwnerConfigurationSession) async throws -> [MemoryLearningJob] { let v: MemoryLearningPage<MemoryLearningJob> = try await request(try learningPath(session) + "/jobs", timeout: 15); guard v.items.count <= 100, v.items.allSatisfy({ learningHash($0.inputHash) }) else { throw HostClientError.contractMismatch }; return v.items }
    public func proposeMemoryLearning(_ session: OwnerConfigurationSession, command: MemoryLearningCommand, clientRequestId: String, beforeDispatch: (@MainActor @Sendable () throws -> Void)? = nil) async throws -> Action { let v: Action = try await request(try learningPath(session) + "/proposals", method: "POST", body: MemoryLearningProposalBody(clientRequestId: try learningID(clientRequestId), command: command), timeout: 15, beforeDispatch: beforeDispatch); guard v.request.botId == session.botID, v.request.tool == "dexter.harness.memory." + command.operation else { throw HostClientError.mutationOutcomeUnknown }; return v }
    public func memoryLearningRequest(_ session: OwnerConfigurationSession, clientRequestId: String, command: MemoryLearningCommand) async throws -> MemoryLearningRequestObservation { let v: MemoryLearningRequestObservation = try await request(try learningPath(session) + "/requests/" + learningID(clientRequestId), timeout: 15); let expected = try JSONDecoder().decode(JSONValue.self, from: JSONEncoder().encode(command)); guard v.clientRequestId == clientRequestId, v.command == nil || v.command == expected, v.action == nil || (v.action?.request.botId == session.botID && v.action?.request.tool == "dexter.harness.memory." + command.operation), (v.action == nil) == (v.command == nil) else { throw HostClientError.contractMismatch }; return v }
    public func memoryLearningReceipt(_ session: OwnerConfigurationSession, actionID: String) async throws -> MemoryLearningReceiptObservation { let v: MemoryLearningReceiptObservation = try await request(try learningPath(session) + "/receipts/" + learningID(actionID), timeout: 15); guard v.action.id == actionID, v.action.request.botId == session.botID, v.receipt == nil || (v.receipt?.actionId == actionID && v.receipt?.botId == session.botID && v.receipt?.ownerId == session.ownerID && v.receipt?.requestHash == v.action.requestHash) else { throw HostClientError.contractMismatch }; return v }
    public func decideMemoryLearning(_ session: OwnerConfigurationSession, clientRequestId: String, command: MemoryLearningCommand, action: Action, decision: ApprovalDecision, beforeDispatch: (@MainActor @Sendable () throws -> Void)? = nil) async throws -> Action { let observed = try await memoryLearningRequest(session, clientRequestId: clientRequestId, command: command); guard observed.action?.id == action.id, observed.action?.requestHash == action.requestHash, observed.action?.request == action.request else { throw HostClientError.forbidden }; let v: Action = try await request("/v1/actions/" + learningID(action.id) + "/decisions", method: "POST", body: ApprovalDecisionInput(decision: decision, requestHash: action.requestHash), timeout: 15, beforeDispatch: beforeDispatch); guard v.id == action.id, v.request == action.request, v.requestHash == action.requestHash else { throw HostClientError.mutationOutcomeUnknown }; return v }
}

public typealias MemoryLearningPolicyInput = MemoryLearningCommand.PolicyUpdate
